#!/usr/bin/python3
"""Tiny Marionette (Firefox) client for headless testing of the single-file page.
Usage (as a module):  from mc import FF ; ff = FF(); ff.start(); ...
"""
import json, os, socket, subprocess, sys, time, base64, tempfile, shutil

FIREFOX = "/Applications/Firefox.app/Contents/MacOS/firefox"


class FF:
    def __init__(self, port=2828, width=1280, height=720):
        self.port = port
        self.width = width
        self.height = height
        self.proc = None
        self.sock = None
        self.msgid = 0
        self.profile = None

    def start(self):
        self.profile = tempfile.mkdtemp(prefix="ffprof_", dir=os.environ.get("TMPDIR", "/tmp"))
        prefs = {
            "marionette.port": self.port,
            "webgl.force-enabled": True,
            "webgl.disabled": False,
            "webgl.enable-webgl2": True,
            "layers.acceleration.force-enabled": True,
            "media.autoplay.default": 0,
            "media.autoplay.blocking_policy": 0,
            "browser.shell.checkDefaultBrowser": False,
            "datareporting.policy.dataSubmissionEnabled": False,
            "toolkit.telemetry.enabled": False,
            "app.update.enabled": False,
            "network.captive-portal-service.enabled": False,
            "privacy.file_unique_origin": False,
            "security.fileuri.strict_origin_policy": False,
            "dom.webaudio.enabled": True,
        }
        with open(os.path.join(self.profile, "user.js"), "w") as f:
            for k, v in prefs.items():
                f.write('user_pref("%s", %s);\n' % (k, json.dumps(v)))
        cmd = [FIREFOX, "-marionette", "-headless", "-no-remote", "-profile", self.profile,
               "--width", str(self.width), "--height", str(self.height)]
        self.proc = subprocess.Popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        # wait for the marionette port
        t0 = time.time()
        while time.time() - t0 < 60:
            try:
                self.sock = socket.create_connection(("127.0.0.1", self.port), timeout=2)
                break
            except OSError:
                time.sleep(0.5)
        else:
            raise RuntimeError("could not connect to marionette")
        self.sock.settimeout(120)
        self._recv()  # greeting
        self.cmd("WebDriver:NewSession", {"capabilities": {}})
        self.cmd("WebDriver:SetWindowRect", {"width": self.width, "height": self.height})

    def _recv(self):
        buf = b""
        while b":" not in buf:
            ch = self.sock.recv(1)
            if not ch:
                raise RuntimeError("socket closed")
            buf += ch
        n = int(buf.split(b":")[0])
        data = b""
        while len(data) < n:
            chunk = self.sock.recv(n - len(data))
            if not chunk:
                raise RuntimeError("socket closed")
            data += chunk
        return json.loads(data.decode("utf-8"))

    def cmd(self, name, params=None):
        self.msgid += 1
        msg = json.dumps([0, self.msgid, name, params or {}])
        self.sock.sendall(("%d:%s" % (len(msg.encode("utf-8")), msg)).encode("utf-8"))
        while True:
            r = self._recv()
            if r[0] == 1 and r[1] == self.msgid:
                if r[2]:
                    raise RuntimeError("marionette error: %s" % json.dumps(r[2]))
                return r[3]

    def get(self, url):
        return self.cmd("WebDriver:Navigate", {"url": url})

    def js(self, script, args=None, timeout=120000):
        r = self.cmd("WebDriver:ExecuteScript", {"script": script, "args": args or [], "scriptTimeout": timeout})
        return r.get("value") if isinstance(r, dict) else r

    def js_async(self, script, args=None, timeout=120000):
        r = self.cmd("WebDriver:ExecuteAsyncScript", {"script": script, "args": args or [], "scriptTimeout": timeout})
        return r.get("value") if isinstance(r, dict) else r

    def screenshot(self, path, full=False):
        r = self.cmd("WebDriver:TakeScreenshot", {"full": full, "hash": False})
        data = base64.b64decode(r["value"])
        with open(path, "wb") as f:
            f.write(data)
        return path

    def stop(self):
        try:
            if self.sock:
                self.cmd("Marionette:Quit")
        except Exception:
            pass
        try:
            if self.proc:
                self.proc.terminate()
                self.proc.wait(timeout=10)
        except Exception:
            try:
                self.proc.kill()
            except Exception:
                pass
        if self.profile:
            shutil.rmtree(self.profile, ignore_errors=True)


if __name__ == "__main__":
    ff = FF()
    try:
        ff.start()
        html = "data:text/html,<canvas id=c></canvas><script>var gl=document.getElementById('c').getContext('webgl2');document.title=gl?('GL:'+gl.getParameter(gl.VERSION)+'|'+gl.getParameter(gl.RENDERER)):'NOGL';</script>"
        ff.get(html)
        time.sleep(1)
        print(ff.js("return document.title"))
    finally:
        ff.stop()

