          "gap at blue finish = %.2f m" % (FIN - fr(tb)))
    # speeds
    print("  max speed R %.1f B %.1f" % (max(fr(t/10, 1) for t in range(0, 400)), max(fb(t/10, 1) for t in range(0, 400))))
    print("  accel at t=20..22 (R):", ["%.1f" % fr(t/2, 2) for t in range(38, 46)])

