'use strict';
/* =====================================================================
   Circuit: Catmull-Rom centreline (centripetal, closed), arc-length table
   C(s) centreline, T(s) tangent, n(s) = normalize(T x up) right-hand normal
   ===================================================================== */
const CIR = { L: 0, NS: 0, DS: 0, px: null, py: null, pz: null, tx: null, ty: null, tz: null, yaw: null, kr: null, turn: 0 };
const FR = { px: 0, py: 0, pz: 0, tx: 0, ty: 0, tz: 0, nx: 0, nz: 0, yaw: 0, kr: 0 };   // scratch frame
let LAP = 1551.65;
let hashCells = null, hashCell = 48, hashN = 0;

function initCircuit() {
  const pts = [[0, 0, 0], [200, 0, 0], [320, 5, 60], [340, 12, 180], [260, 20, 260], [120, 15, 240],
               [60, 8, 320], [-80, 4, 340], [-200, 0, 260], [-240, 0, 120], [-160, 0, 40], [-80, 0, 0]]
    .map(p => new THREE.Vector3(p[0], p[1], p[2]));
  const curve = new THREE.CatmullRomCurve3(pts, true, 'centripetal');
  curve.arcLengthDivisions = 4000;                    // >= 2000 arc-length samples
  curve.updateArcLengths();
  const L = curve.getLength();
  const NS = Math.round(L / 0.5);
  const DS = L / NS;
  const px = new Float64Array(NS + 1), py = new Float64Array(NS + 1), pz = new Float64Array(NS + 1);
  const tx = new Float64Array(NS + 1), ty = new Float64Array(NS + 1), tz = new Float64Array(NS + 1);
  const yaw = new Float64Array(NS + 1), kr = new Float64Array(NS + 1);
  for (let i = 0; i < NS; i++) {
    const p = curve.getPointAt(i / NS);
    px[i] = p.x; py[i] = p.y; pz[i] = p.z;
  }
  px[NS] = px[0]; py[NS] = py[0]; pz[NS] = pz[0];
  for (let i = 0; i < NS; i++) {
    const a = (i - 1 + NS) % NS, b = (i + 1) % NS;
    let x = px[b] - px[a], y = py[b] - py[a], z = pz[b] - pz[a];
    const m = Math.hypot(x, y, z) || 1;
    tx[i] = x / m; ty[i] = y / m; tz[i] = z / m;
  }
  tx[NS] = tx[0]; ty[NS] = ty[0]; tz[NS] = tz[0];
  yaw[0] = Math.atan2(-tz[0], tx[0]);
  for (let i = 1; i <= NS; i++) {
    let a = Math.atan2(-tz[i], tx[i]);
    while (a - yaw[i - 1] > Math.PI) a -= 2 * Math.PI;
    while (a - yaw[i - 1] < -Math.PI) a += 2 * Math.PI;
    yaw[i] = a;
  }
  const turn = yaw[NS] - yaw[0];                      // total heading change around the lap (~ +-2pi)
  const yawAt = (i) => (i < 0 ? yaw[i + NS] - turn : (i > NS ? yaw[i - NS] + turn : yaw[i]));
  const raw = new Float64Array(NS + 1);
  for (let i = 0; i <= NS; i++) raw[i] = -(yawAt(i + 2) - yawAt(i - 2)) / (4 * DS);   // right turns positive
  for (let i = 0; i <= NS; i++) {
    let acc = 0, w = 0;
    for (let k = -6; k <= 6; k++) { let j = i + k; j = ((j % NS) + NS) % NS; acc += raw[j]; w++; }
    kr[i] = acc / w;
  }
  kr[NS] = kr[0];
  Object.assign(CIR, { L, NS, DS, px, py, pz, tx, ty, tz, yaw, kr, turn, curve });
  LAP = L;
  // coarse spatial hash (4 m spacing) for nearest-centreline queries
  hashN = 0; hashCells = new Map();
  for (let i = 0; i < NS; i += 8) {
    const key = Math.floor(px[i] / hashCell) * 4096 + Math.floor(pz[i] / hashCell);
    let a = hashCells.get(key); if (!a) { a = []; hashCells.set(key, a); }
    a.push(i); hashN++;
  }
}

/* interpolated frame at arc-length s (wraps modulo L) -> writes into o (default FR) */
function frameAt(s, o) {
  o = o || FR;
  const L = CIR.L;
  let u = s % L; if (u < 0) u += L;
  const f = u / CIR.DS;
  let i = Math.floor(f); if (i >= CIR.NS) i = CIR.NS - 1;
  const w = f - i, w0 = 1 - w;
  o.px = CIR.px[i] * w0 + CIR.px[i + 1] * w;
  o.py = CIR.py[i] * w0 + CIR.py[i + 1] * w;
  o.pz = CIR.pz[i] * w0 + CIR.pz[i + 1] * w;
  let x = CIR.tx[i] * w0 + CIR.tx[i + 1] * w, y = CIR.ty[i] * w0 + CIR.ty[i + 1] * w, z = CIR.tz[i] * w0 + CIR.tz[i + 1] * w;
  const m = Math.hypot(x, y, z) || 1;
  o.tx = x / m; o.ty = y / m; o.tz = z / m;
  const h = Math.hypot(o.tx, o.tz) || 1;
  o.nx = -o.tz / h; o.nz = o.tx / h;                 // n = normalize(T x (0,1,0)) = (-Tz, 0, Tx)/|.|
  o.yaw = CIR.yaw[i] * w0 + CIR.yaw[i + 1] * w;
  o.kr = CIR.kr[i] * w0 + CIR.kr[i + 1] * w;
  return o;
}
function C(s, out) { frameAt(s); return (out || new THREE.Vector3()).set(FR.px, FR.py, FR.pz); }
function Tn(s, out) { frameAt(s); return (out || new THREE.Vector3()).set(FR.tx, FR.ty, FR.tz); }
function Nr(s, out) { frameAt(s); return (out || new THREE.Vector3()).set(FR.nx, 0, FR.nz); }
function roadYAt(s) { frameAt(s); return FR.py - ROAD_DROP; }

/* nearest centreline sample to (x,z): returns true and fills NEAR{idx,dist,y} if within maxD */
const NEAR = { idx: 0, dist: 1e9, y: 0, s: 0 };
function nearestTrack(x, z, maxD) {
  const cx = Math.floor(x / hashCell), cz = Math.floor(z / hashCell);
  const rings = Math.max(1, Math.ceil(maxD / hashCell));
  let best = 1e18, bi = -1;
  for (let a = -rings; a <= rings; a++) {
    for (let b = -rings; b <= rings; b++) {
      const arr = hashCells.get((cx + a) * 4096 + (cz + b));
      if (!arr) continue;
      for (let k = 0; k < arr.length; k++) {
        const i = arr[k];
        const dx = CIR.px[i] - x, dz = CIR.pz[i] - z, d2 = dx * dx + dz * dz;
        if (d2 < best) { best = d2; bi = i; }
      }
    }
  }
  if (bi < 0) { NEAR.dist = 1e9; return false; }
  // refine on the fine samples around the coarse winner
  let fb = 1e18, fi = bi;
  for (let k = -9; k <= 9; k++) {
    const i = (((bi + k) % CIR.NS) + CIR.NS) % CIR.NS;
    const dx = CIR.px[i] - x, dz = CIR.pz[i] - z, d2 = dx * dx + dz * dz;
    if (d2 < fb) { fb = d2; fi = i; }
  }
  NEAR.idx = fi; NEAR.dist = Math.sqrt(fb); NEAR.y = CIR.py[fi]; NEAR.s = fi * CIR.DS;
  return NEAR.dist <= maxD;
}

