'use strict';
/* =====================================================================
   Procedural textures (all drawn on detached in-memory canvases)
   ===================================================================== */
function ihash(x, y, seed) {                 // deterministic integer hash noise in [0,1)
  let h = (Math.imul(x | 0, 374761393) + Math.imul(y | 0, 668265263) + Math.imul(seed | 0, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h = h ^ (h >>> 16);
  return (h >>> 0) / 4294967296;
}
/* periodic smooth value noise, period p lattice cells over unit square */
function vnoise(u, v, p, seed) {
  const x = u * p, y = v * p, xi = Math.floor(x), yi = Math.floor(y);
  const fx = x - xi, fy = y - yi, sx = fx * fx * (3 - 2 * fx), sy = fy * fy * (3 - 2 * fy);
  const x0 = ((xi % p) + p) % p, x1 = (x0 + 1) % p, y0 = ((yi % p) + p) % p, y1 = (y0 + 1) % p;
  const a = ihash(x0, y0, seed), b = ihash(x1, y0, seed), c = ihash(x0, y1, seed), d = ihash(x1, y1, seed);
  return (a + (b - a) * sx) + ((c + (d - c) * sx) - (a + (b - a) * sx)) * sy;
}
function fbm(u, v, base, oct, seed) {
  let a = 0, w = 0.5, p = base, tot = 0;
  for (let i = 0; i < oct; i++) { a += w * vnoise(u, v, p, seed + i * 17); tot += w; w *= 0.5; p *= 2; }
  return a / tot;
}

/* ---------- night sky: gradient + stars + moon + warm city glow (equirectangular) ---------- */
const MOON_DIR = new THREE.Vector3(0.86, 0.24, 0.45).normalize();
const GLOW_DIR = new THREE.Vector3(-0.95, 0, 0.3).normalize();
function dirToPx(d, W, H) {
  const u = Math.atan2(d.z, d.x) / (2 * Math.PI) + 0.5, v = Math.asin(clamp(d.y, -1, 1)) / Math.PI + 0.5;
  return [u * W, (1 - v) * H];
}
function makeSkyTexture() {
  const W = 4096, H = 2048, c = mkCanvas(W, H), g = c.getContext('2d');
  const grad = g.createLinearGradient(0, 0, 0, H);
  grad.addColorStop(0.00, '#02040a');
  grad.addColorStop(0.20, '#03060e');
  grad.addColorStop(0.38, '#050a16');
  grad.addColorStop(0.46, '#0a1424');
  grad.addColorStop(0.495, '#101a2a');
  grad.addColorStop(0.50, '#0e1622');
  grad.addColorStop(1.00, '#0e1622');
