  const [gx, gy] = dirToPx(GLOW_DIR, W, H);
  for (let k = -1; k <= 1; k++) {
    const rg = g.createRadialGradient(gx + k * W, gy, 0, gx + k * W, gy, W * 0.16);
    rg.addColorStop(0, 'rgba(255,150,70,0.34)'); rg.addColorStop(0.4, 'rgba(210,100,50,0.14)'); rg.addColorStop(1, 'rgba(120,60,40,0)');
    g.save(); g.translate(0, 0); g.scale(1, 0.30); g.translate(0, gy * (1 / 0.30 - 1));
    g.fillStyle = rg; g.fillRect(gx + k * W - W * 0.2, 0, W * 0.4, H / 0.30);
    g.restore();
