  const hz = g.createLinearGradient(0, H * 0.44, 0, H * 0.5);
  hz.addColorStop(0, 'rgba(30,48,74,0)'); hz.addColorStop(1, 'rgba(30,48,74,0.35)');
  g.fillStyle = hz; g.fillRect(0, H * 0.44, W, H * 0.06);
  // stars (seeded): more toward the zenith, a few bright ones
  for (let i = 0; i < 5200; i++) {
    const y = 2 * simRng() - 1, th = simRng() * Math.PI * 2, r = Math.sqrt(1 - y * y);
    if (y < 0.04) continue;
    const [sx, sy] = dirToPx({ x: r * Math.cos(th), y: y, z: r * Math.sin(th) }, W, H);
    const m = simRng(), bright = m < 0.02 ? 1.0 : (m < 0.12 ? 0.62 : 0.28 + 0.25 * simRng());
