}

/* ---------- asphalt: colour (with edge lines), roughness (wet patches), bump grain ---------- */
function makeAsphalt() {
  const S = 1024, c = mkCanvas(S, S), g = c.getContext('2d'), img = g.createImageData(S, S), d = img.data;
  for (let y = 0; y < S; y++) {
    const v = y / S;
