'use strict';
/* =====================================================================
   Scene core: renderer, camera, PMREM night environment, fog, lights,
   material patching (baked floodlight pools + wet-road lamp reflections)
   ===================================================================== */
const G = { ready: false, aspect: 16 / 9 };
const FOG_HEX = 0x0d141e;                       // dark blue-grey haze (<= #1a2230)
const FOG_DENSITY = 0.0034;
const NLAMP_MAX = 40;
const LAMPS = [];                               // {x,y,z, ax,ay,az, s, side}
G.uLamps = { value: [] };
G.uRain = { value: [new THREE.Vector4(0, -50, 0, 0), new THREE.Vector4(0, -50, 0, 0)] };
for (let i = 0; i < NLAMP_MAX; i++) G.uLamps.value.push(new THREE.Vector3(0, -999, 0));

function initRenderer() {
  const canvas = document.getElementById('stage');
  const renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(window.innerWidth, window.innerHeight, false);
  renderer.outputEncoding = THREE.sRGBEncoding;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 0.95;
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.setClearColor(0x05070c, 1);
  G.renderer = renderer;
  G.scene = new THREE.Scene();
  G.scene.background = makeSkyTexture();
  G.scene.fog = new THREE.FogExp2(FOG_HEX, FOG_DENSITY);
  G.camera = new THREE.PerspectiveCamera(35, window.innerWidth / Math.max(1, window.innerHeight), 0.1, 3000);
  G.aniso = Math.min(8, renderer.capabilities.getMaxAnisotropy ? renderer.capabilities.getMaxAnisotropy() : 4);
}

/* ---- night environment (PMREM from an in-memory scene: dark sky + bright floodlight panels) ---- */
function buildEnvironment() {
  const es = new THREE.Scene();
  const sg = new THREE.SphereGeometry(60, 48, 24);
  const cols = [], p = sg.attributes.position;
  for (let i = 0; i < p.count; i++) {
    const y = p.getY(i) / 60;                       // -1..1
    const t = smooth(-0.1, 0.9, y);
    const r = lerp(0.050, 0.003, t), g = lerp(0.070, 0.006, t), b = lerp(0.105, 0.016, t);
    cols.push(r, g, b);
  }
  sg.setAttribute('color', new THREE.Float32BufferAttribute(cols, 3));
  es.add(new THREE.Mesh(sg, new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.BackSide, fog: false })));
  const panel = (az, el, w, h, r, g, b) => {
    const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshBasicMaterial({ color: new THREE.Color(r, g, b), side: THREE.DoubleSide, fog: false }));
    const d = 45, ce = Math.cos(el);
    m.position.set(d * ce * Math.cos(az), d * Math.sin(el), d * ce * Math.sin(az));
    m.lookAt(0, 0, 0);
    es.add(m);
  };
  const D = Math.PI / 180;
  // floodlight banks (high, around the compass) - cool white HDR
  for (let k = 0; k < 8; k++) panel((k * 45 + 12) * D, (52 + (k % 2) * 10) * D, 12, 5, 9, 10, 12);
  // two big overhead softboxes for crisp roof reflections
  panel(20 * D, 78 * D, 16, 7, 5.5, 6.2, 7.2);
  panel(200 * D, 70 * D, 14, 6, 4.5, 5.2, 6.2);
  // distant low floodlight pinpoints along the horizon (rim highlights down the sides)
  for (let k = 0; k < 16; k++) panel((k * 22.5 + 5) * D, (9 + (k % 3) * 3) * D, 3.2, 1.6, 6, 6.8, 8);
  // moon
  panel(Math.atan2(MOON_DIR.z, MOON_DIR.x), Math.asin(MOON_DIR.y), 5, 5, 3.2, 4.0, 6.0);
  // warm city glow band low on one horizon
  panel(Math.atan2(GLOW_DIR.z, GLOW_DIR.x), 5 * D, 40, 7, 0.9, 0.42, 0.18);
  const pm = new THREE.PMREMGenerator(G.renderer);
  pm.compileEquirectangularShader && pm.compileEquirectangularShader();
  const rt = pm.fromScene(es, 0.01);
  G.envTex = rt.texture;
  G.scene.environment = G.envTex;
  pm.dispose();
  es.traverse(o => { if (o.geometry) o.geometry.dispose(); if (o.material) o.material.dispose(); });
}

/* ---- material patching: baked floodlight pools (aBake attribute) + analytic wet lamp reflections ---- */
function patchMaterial(mat, o) {
  o = o || {};
  const key = 'p|' + (o.k1 === undefined ? 0 : o.k1) + '|' + (o.k2 || 0) + '|' + (o.road ? 'R' : '') + '|' + (o.refl || 0) + '|' + (o.facing ? 'F' : '');
  mat.customProgramCacheKey = function () { return key; };
  mat.onBeforeCompile = function (sh) {
    let defs = '#define BAKE_K1 ' + (o.k1 === undefined ? 0 : o.k1).toFixed(4) + '\n#define BAKE_K2 ' + (o.k2 || 0).toFixed(4) + '\n';
    if (o.road) { defs += '#define ROAD_WET\n#define NLAMP ' + NLAMP_MAX + '\n#define REFL_GAIN ' + (o.refl || 1).toFixed(3) + '\n'; sh.uniforms.uLamps = G.uLamps; sh.uniforms.uRain = G.uRain; }
    sh.vertexShader = sh.vertexShader
      .replace('#include <common>', '#include <common>\nattribute float aBake;\nvarying float vBake;\nvarying vec3 vWPos;')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\nvBake = aBake;\nvWPos = (modelMatrix * vec4(transformed, 1.0)).xyz;');
    let fcommon = '#include <common>\nvarying float vBake;\nvarying vec3 vWPos;\n';
    if (o.road) fcommon += 'uniform vec3 uLamps[NLAMP];\nuniform vec4 uRain[2];\n';
    let inj = 'totalEmissiveRadiance += (diffuseColor.rgb * BAKE_K1 + vec3(BAKE_K2)) * vBake * vec3(0.78, 0.89, 1.0);\n';
    if (o.road) inj += [
      '{',
      '  vec3 V = normalize(cameraPosition - vWPos);',
      '  float wet = clamp(1.30 - roughnessFactor * 2.6, 0.0, 1.0);',
      '  vec2 vh = V.xz; float vl = length(vh) + 1e-4; vec2 b1 = vh / vl; vec2 b2 = vec2(-b1.y, b1.x);',
      '  vec3 acc = vec3(0.0);',
      '  for (int i = 0; i < NLAMP; i++) {',
      '    vec3 Lv = uLamps[i] - vWPos; float d2 = dot(Lv, Lv);',
      '    if (d2 > 6400.0) continue;',
      '    vec3 D = Lv * inversesqrt(d2); vec3 H = normalize(D + V);',
      '    float p1 = dot(H.xz, b1), p2 = dot(H.xz, b2);',
      '    float lobe = exp(-(p1 * p1 / 0.030 + p2 * p2 / 0.0016));',
      '    float F = 0.04 + 0.96 * pow(1.0 - max(dot(V, H), 0.0), 5.0);',
      '    acc += lobe * F / (1.0 + d2 * 0.0008);',
      '  }',
      '  totalEmissiveRadiance += acc * wet * vec3(0.78, 0.89, 1.0) * REFL_GAIN * 14.0;',
      '  vec3 racc = vec3(0.0);',
      '  for (int j = 0; j < 2; j++) {',
      '    vec3 Lv = uRain[j].xyz - vWPos; float d2 = dot(Lv, Lv);',
      '    if (d2 > 2500.0 || uRain[j].w < 0.01) continue;',
      '    vec3 D = Lv * inversesqrt(d2); vec3 H = normalize(D + V);',
      '    float p1 = dot(H.xz, b1), p2 = dot(H.xz, b2);',
      '    float lobe = exp(-(p1 * p1 / 0.080 + p2 * p2 / 0.0040));',
      '    float F = 0.04 + 0.96 * pow(1.0 - max(dot(V, H), 0.0), 5.0);',
      '    racc += lobe * F * uRain[j].w / (1.0 + d2 * 0.02);',
      '  }',
      '  totalEmissiveRadiance += racc * wet * vec3(1.0, 0.10, 0.06) * 5.0;',
      '}'
    ].join('\n');
    sh.fragmentShader = sh.fragmentShader
      .replace('#include <common>', fcommon)
      .replace('#include <emissivemap_fragment>', '#include <emissivemap_fragment>\n' + inj);
    sh.fragmentShader = defs + sh.fragmentShader;
    sh.vertexShader = defs + sh.vertexShader;
  };
  return mat;
}
function stdMat(o) { return new THREE.MeshStandardMaterial(o); }

