    LAMPS.push({ x: x, y: y, z: z, ax: ax / m, ay: ay / m, az: az / m, s: s, side: side, gx: x, gz: z, ground: FR.py });
    s += 60 + simRng() * 20; side = -side;
  }
  for (let i = 0; i < NLAMP_MAX; i++) {
