/* periodic smooth value noise, period p lattice cells over unit square */
function vnoise(u, v, p, seed) {
  const x = u * p, y = v * p, xi = Math.floor(x), yi = Math.floor(y);
  const fx = x - xi, fy = y - yi, sx = fx * fx * (3 - 2 * fx), sy = fy * fy * (3 - 2 * fy);
