'use strict';
/* =====================================================================
   Cars: two original F1-style single-seaters, 100% code-generated geometry.
   Local frame: +x forward, +y up, +z right; origin = floor centre midway between axles.
   ===================================================================== */
const CAR_X0 = -2.8, CAR_LEN = 5.6;
const AXLE_F = 1.8, AXLE_R = -1.8, WHEEL_R = 0.36, AXLE_Y = 0.31;
const HOOP_X = 0.14;                                     // roll hoop position (the T-cam sits 0.2 m behind it)

function liveryU(g) { const p = g.attributes.position, uv = g.attributes.uv; for (let i = 0; i < p.count; i++) uv.setX(i, (p.getX(i) - CAR_X0) / CAR_LEN); return g; }

function slabGeo(pts, y0, y1) {                          // flat convex slab from an XZ polygon
  const M = pts.length; let A = 0, cx = 0, cz = 0;
  for (let j = 0; j < M; j++) { const a = pts[j], b = pts[(j + 1) % M]; A += a[0] * b[1] - b[0] * a[1]; cx += a[0] / M; cz += a[1] / M; }
  const pos = [], idx = [], uv = [];
  let b = 0;
  pos.push(cx, y1, cz); uv.push(0.5, 0.5); pts.forEach(p => { pos.push(p[0], y1, p[1]); uv.push(p[0], p[1]); });
  for (let j = 0; j < M; j++) { const a = b + 1 + j, c = b + 1 + ((j + 1) % M); if (A > 0) idx.push(b, c, a); else idx.push(b, a, c); }
  b = pos.length / 3;
  pos.push(cx, y0, cz); uv.push(0.5, 0.5); pts.forEach(p => { pos.push(p[0], y0, p[1]); uv.push(p[0], p[1]); });
  for (let j = 0; j < M; j++) { const a = b + 1 + j, c = b + 1 + ((j + 1) % M); if (A > 0) idx.push(b, a, c); else idx.push(b, c, a); }
  for (let j = 0; j < M; j++) {
    const p = pts[j], q = pts[(j + 1) % M]; b = pos.length / 3;
    pos.push(p[0], y0, p[1], q[0], y0, q[1], q[0], y1, q[1], p[0], y1, p[1]); uv.push(0, 0, 1, 0, 1, 1, 0, 1);
    if (A > 0) idx.push(b, b + 2, b + 1, b, b + 3, b + 2); else idx.push(b, b + 1, b + 2, b, b + 2, b + 3);
  }
  return geoFrom(pos, idx, uv);
}
function plateGeo(x0, z0, x1, z1, y0, y1, th) {          // thin vertical plate between two XZ points
  const dx = x1 - x0, dz = z1 - z0, L = Math.hypot(dx, dz);
  const g = new THREE.BoxGeometry(L, y1 - y0, th);
  g.rotateY(Math.atan2(-dz, dx)); g.translate((x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2);
