/* Surface-conforming decal patch sampled from the same loft stations (grid x in [x0,x1], ring angle a in [a0,a1]) */
function loftDecal(st, x0, x1, a0, a1, off, nx, na, swap, flipU) {
  st = st.slice().sort((a, b) => a.x - b.x);
  const ring = (s, a) => { const e = 2 / (s.e || 2.4), hb = s.hb === undefined ? s.ht : s.hb, py = -Math.cos(a), pz = Math.sin(a); return [s.x, s.y + (py >= 0 ? s.ht : hb) * sgnPow(py, e), s.z + s.w * sgnPow(pz, e)]; };
  const at = (x, a) => {
    let i = 0; while (i < st.length - 2 && x > st[i + 1].x) i++;
    const f = clamp((x - st[i].x) / (st[i + 1].x - st[i].x), 0, 1), p0 = ring(st[i], a), p1 = ring(st[i + 1], a);
    return [lerp(p0[0], p1[0], f), lerp(p0[1], p1[1], f), lerp(p0[2], p1[2], f), lerp(st[i].y, st[i + 1].y, f), lerp(st[i].z, st[i + 1].z, f)];
  };
  const pos = [], uv = [], idx = [], da = 0.01 * Math.sign(a1 - a0);
  let n0 = null;
  for (let j = 0; j <= na; j++) for (let i = 0; i <= nx; i++) {
    const x = lerp(x0, x1, i / nx), a = lerp(a0, a1, j / na);
    const p = at(x, a), px = at(x + 0.01, a), pa = at(x, a + da);
    const tx = [px[0] - p[0], px[1] - p[1], px[2] - p[2]], ta = [pa[0] - p[0], pa[1] - p[1], pa[2] - p[2]];
    let n = [tx[1] * ta[2] - tx[2] * ta[1], tx[2] * ta[0] - tx[0] * ta[2], tx[0] * ta[1] - tx[1] * ta[0]];
    const m = Math.hypot(n[0], n[1], n[2]) || 1; n = [n[0] / m, n[1] / m, n[2] / m];
    if (n[1] * (p[1] - p[3]) + n[2] * (p[2] - p[4]) < 0) n = [-n[0], -n[1], -n[2]];
    if (!n0) n0 = n;
    pos.push(p[0] + n[0] * off, p[1] + n[1] * off, p[2] + n[2] * off);
    const u = swap ? j / na : i / nx, v = swap ? i / nx : j / na;
    uv.push(flipU ? 1 - u : u, v);
  }
  const R = nx + 1;
  const e1 = [pos[3] - pos[0], pos[4] - pos[1], pos[5] - pos[2]], e2 = [pos[3 * R] - pos[0], pos[3 * R + 1] - pos[1], pos[3 * R + 2] - pos[2]];
  const g = [e1[1] * e2[2] - e1[2] * e2[1], e1[2] * e2[0] - e1[0] * e2[2], e1[0] * e2[1] - e1[1] * e2[0]];
  const flip = (g[0] * n0[0] + g[1] * n0[1] + g[2] * n0[2]) < 0;
  for (let j = 0; j < na; j++) for (let i = 0; i < nx; i++) {
    const a = j * R + i, b = a + 1, c = a + R, d = c + 1;
    if (!flip) idx.push(a, b, c, b, d, c); else idx.push(a, c, b, b, c, d);
  }
  return geoFrom(pos, idx, uv);
}

