/* =====================================================================
   Utilities: colour, detached canvases, procedural geometry kit
   ===================================================================== */
function col(hex) { return new THREE.Color(hex).convertSRGBToLinear(); }   // display sRGB hex -> linear working colour
function mkCanvas(w, h) { const c = document.createElement('canvas'); c.width = w; c.height = h; return c; }   // detached, never appended
function canvasTex(c, o) {
  o = o || {};
  const t = new THREE.CanvasTexture(c);
  t.encoding = o.linear ? THREE.LinearEncoding : THREE.sRGBEncoding;
  t.wrapS = o.wrapS || THREE.ClampToEdgeWrapping;
