'use strict';
/* =====================================================================
   renderAt(simTime): pure function of simTime -> poses, lights, FX, camera
   ===================================================================== */
const R_ = { cars: [], pose: [{}, {}], mid: null, shot: 1, camPos: null, camTgt: null, camUp: null, camVel: null };
const SHOTS = [0, 5, 11, 15, 20, 24, 30, 34];             // start times of shots 1..8
function shotIndex(t) { let k = 0; for (let i = 0; i < SHOTS.length; i++) if (t >= SHOTS[i]) k = i; return k + 1; }
const _kk = [{}, {}];

function yawAtTime(i, t) {
  const k = carKin(i, t, _kk[i]); frameAt(k.s);
  const slip = clamp(Math.atan2(k.dd, Math.max(k.v, 0.5)), -0.35, 0.35);
  return FR.yaw - slip;
}
/* full kinematic + attitude state of a car at time t */
function carPose(i, t, o) {
  const k = carKin(i, t, _kk[i]);
  frameAt(k.s);
  o.s = k.s; o.v = k.v; o.a = k.a; o.d = k.d; o.dd = k.dd;
  o.px = FR.px + FR.nx * k.d; o.py = FR.py; o.pz = FR.pz + FR.nz * k.d;
  const slip = clamp(Math.atan2(k.dd, Math.max(k.v, 0.5)), -0.35, 0.35);
  o.yaw = FR.yaw - slip;
  o.gradPitch = Math.asin(clamp(FR.ty, -1, 1));
  o.kr = FR.kr;
  const e = 0.02;
  o.omega = (yawAtTime(i, Math.min(DURATION, t + e)) - yawAtTime(i, Math.max(0, t - e))) / (Math.min(DURATION, t + e) - Math.max(0, t - e) || 1);
  o.steer = clamp(Math.atan(WHEELBASE * o.omega / Math.max(o.v, 4)), -0.5, 0.5);
  o.roll = clamp(0.0012 * o.v * o.omega, -0.05, 0.05);
  o.pitchDyn = clamp(o.a > 0 ? 0.0005 * o.a : 0.0009 * o.a, -0.035, 0.02);
  o.hx = Math.cos(o.yaw); o.hz = -Math.sin(o.yaw);        // horizontal heading
  return o;
}
function wheelspinExtra(t) {                              // extra rear-wheel rotation (rad) during the launch, closed form
  if (t <= 3.0) return 0;
  const t1 = Math.min(t, 6.5); let acc = 0; const n = 28, dt = (t1 - 3.0) / n;
  for (let i = 0; i < n; i++) {
    const tau = 3.0 + (i + 0.5) * dt, x = (tau - 3.5) / 0.85;
    acc += Math.max(0, hermiteEval(KH[0].s, tau, 1)) * 0.0 + (95 * Math.exp(-x * x)) * dt;
  }
  return acc;
}
/* disc temperature 0..1+: braking power convolved with an exponential cooling kernel (pure function of t) */
function discGlow(i, t) {
  let acc = 0; const n = 36, span = 4.2, dt = span / n;
  for (let j = 0; j < n; j++) {
    const tau = t - (j + 0.5) * dt; if (tau < 0) break;
    const a = hermiteEval(KH[i].s, tau, 2), v = hermiteEval(KH[i].s, tau, 1);
    const p = Math.max(0, -a) / 32 * clamp(v / 40, 0.3, 1.4);
    acc += p * Math.exp(-(j + 0.5) * dt / 1.15) * dt;
  }
  return clamp(acc * 1.15, 0, 1.6);
}

const _tmpV = new THREE.Vector3(), _tmpV2 = new THREE.Vector3(), _tmpQ = new THREE.Quaternion(), _camUp = new THREE.Vector3();
let _lastFov = -1, _lastAspect = -1;

function poseCar(i, t) {
  const car = R_.cars[i], o = R_.pose[i];
  carPose(i, t, o);
  car.root.position.set(o.px, o.py, o.pz);
  car.root.rotation.set(0, o.yaw, o.gradPitch, 'YZX');
  car.body.rotation.set(o.roll, 0, o.pitchDyn, 'YZX');
  // wheels
  const dist = o.s, base = -dist / WHEEL_R;
  const extra = wheelspinExtra(t);
  for (const k in car.wheels) {
    const w = car.wheels[k];
