    let fcommon = '#include <common>\nvarying float vBake;\nvarying vec3 vWPos;\n';
    if (o.road) fcommon += 'uniform vec3 uLamps[NLAMP];\nuniform vec4 uRain[2];\n';
    let inj = 'totalEmissiveRadiance += (diffuseColor.rgb * BAKE_K1 + vec3(BAKE_K2)) * vBake * vec3(0.78, 0.89, 1.0);\n';
    if (o.road) inj += [
      '{',
      '  vec3 V = normalize(cameraPosition - vWPos);',
      '  float wet = clamp(1.30 - roughnessFactor * 2.6, 0.0, 1.0);',
      '  vec2 vh = V.xz; float vl = length(vh) + 1e-4; vec2 b1 = vh / vl; vec2 b2 = vec2(-b1.y, b1.x);',
      '  vec3 acc = vec3(0.0);',
      '  for (int i = 0; i < NLAMP; i++) {',
      '    vec3 Lv = uLamps[i] - vWPos; float d2 = dot(Lv, Lv);',
      '    if (d2 > 6400.0) continue;',
      '    vec3 D = Lv * inversesqrt(d2); vec3 H = normalize(D + V);',
      '    float p1 = dot(H.xz, b1), p2 = dot(H.xz, b2);',
      '    float lobe = exp(-(p1 * p1 / 0.030 + p2 * p2 / 0.0016));',
      '    float F = 0.04 + 0.96 * pow(1.0 - max(dot(V, H), 0.0), 5.0);',
      '    acc += lobe * F / (1.0 + d2 * 0.0008);',
      '  }',
      '  totalEmissiveRadiance += acc * wet * vec3(0.78, 0.89, 1.0) * REFL_GAIN * 14.0;',
      '  vec3 racc = vec3(0.0);',
      '  for (int j = 0; j < 2; j++) {',
      '    vec3 Lv = uRain[j].xyz - vWPos; float d2 = dot(Lv, Lv);',
      '    if (d2 > 2500.0 || uRain[j].w < 0.01) continue;',
      '    vec3 D = Lv * inversesqrt(d2); vec3 H = normalize(D + V);',
      '    float p1 = dot(H.xz, b1), p2 = dot(H.xz, b2);',
      '    float lobe = exp(-(p1 * p1 / 0.080 + p2 * p2 / 0.0040));',
      '    float F = 0.04 + 0.96 * pow(1.0 - max(dot(V, H), 0.0), 5.0);',
      '    racc += lobe * F * uRain[j].w / (1.0 + d2 * 0.02);',
      '  }',
      '  totalEmissiveRadiance += racc * wet * vec3(1.0, 0.10, 0.06) * 5.0;',
      '}'
