'use strict';
/* =====================================================================
   F1 NIGHT DUEL - core: constants, seeded PRNG, PCHIP kinematics table
   Everything the cars do is a pure function of simTime (no integration).
   ===================================================================== */
const THREE_OK = (typeof THREE !== 'undefined');     // UI / state machine still work if the CDN script is blocked
const DURATION = 40;
const SIM_SEED = 42;
const FINISH_S = 1551.65;
const WHEELBASE = 3.6;
const ROAD_HALF = 7.0;
const ROAD_DROP = 0.05;            // asphalt sits this far below the centreline (floor reference)
const LIGHT_ON_TIMES = [0.5, 1.0, 1.5, 2.0, 2.5];
const LIGHTS_OUT_T = 3.0;
const DRS_OPEN_T = 33.5;
const KMH200 = 200 / 3.6;

/* ---- seeded PRNG (Mulberry32). Never Math.random(). ---- */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
let simRng = mulberry32(SIM_SEED);          // all procedural geometry / particle seeds / perturbations
function resetSimRng() { simRng = mulberry32(SIM_SEED); }

/* ---- small math helpers ---- */
const clamp = (x, a, b) => (x < a ? a : (x > b ? b : x));
const lerp = (a, b, t) => a + (b - a) * t;
const smooth = (a, b, x) => { const t = clamp((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); };
const fract = (x) => x - Math.floor(x);
const sgnPow = (x, e) => Math.sign(x) * Math.pow(Math.abs(x), e);

/* ---- monotone cubic Hermite (PCHIP, Fritsch-Butland weighted harmonic tangents) ---- */
function pchipSlopes(x, y) {
  const n = x.length, h = [], m = [], d = new Array(n).fill(0);
  for (let i = 0; i < n - 1; i++) { h.push(x[i + 1] - x[i]); m.push((y[i + 1] - y[i]) / h[i]); }
  for (let k = 1; k < n - 1; k++) {
    if (m[k - 1] * m[k] > 0) {
      const w1 = 2 * h[k] + h[k - 1], w2 = h[k] + 2 * h[k - 1];
      d[k] = (w1 + w2) / (w1 / m[k - 1] + w2 / m[k]);
    } else d[k] = 0;
  }
  const edge = (h0, h1, m0, m1) => {
    let dd = ((2 * h0 + h1) * m0 - h0 * m1) / (h0 + h1);
    if (Math.sign(dd) !== Math.sign(m0)) dd = 0;
    else if (Math.sign(m0) !== Math.sign(m1) && Math.abs(dd) > 3 * Math.abs(m0)) dd = 3 * m0;
    return dd;
  };
  d[0] = edge(h[0], h[1], m[0], m[1]);
  d[n - 1] = edge(h[n - 2], h[n - 3], m[n - 2], m[n - 3]);
  return d;
}
function makeHermite(x, y) { return { x: x, y: y, d: pchipSlopes(x, y), n: x.length }; }
function hermiteEval(H, t, order) {
  const n = H.n;
  let k = Math.floor(t - H.x[0]);          // uniform unit knots
  if (k < 0) k = 0; else if (k > n - 2) k = n - 2;
  const h = H.x[k + 1] - H.x[k];
  const u = (t - H.x[k]) / h;
  const y0 = H.y[k], y1 = H.y[k + 1], d0 = H.d[k] * h, d1 = H.d[k + 1] * h;
