}
function solveTime(i, sTarget, lo, hi) {
  for (let k = 0; k < 60; k++) {
    const mid = 0.5 * (lo + hi);
    if (hermiteEval(KH[i].s, mid, 0) < sTarget) lo = mid; else hi = mid;
