}
const T_FIN_R = solveTime(0, FINISH_S, 30, 40);    // ~36.54
const T_FIN_B = solveTime(1, FINISH_S, 30, 40);    // ~36.49  (blue takes the flag)
const T_PASS_START = 33.3;
function speedOf(i, t) { return hermiteEval(KH[i].s, clamp(t, 0, DURATION), 1); }
function accelOf(i, t) { return hermiteEval(KH[i].s, clamp(t, 0, DURATION), 2); }

/* grandstand camera-flash schedule (seeded once at startup; shared by visuals and audio) */
const FLASH_COUNT = 150;
const FLASH_TIMES = [];
(function () {
  const span = DURATION - T_FIN_B - 0.25;
  for (let i = 0; i < FLASH_COUNT; i++) {
    const u = i / FLASH_COUNT;                       // burst: dense right after the flag, thinning out
    FLASH_TIMES.push(T_FIN_B + 0.03 + span * (1 - Math.pow(1 - u, 1.8)) + (simRng() - 0.5) * 0.05);
  }
  FLASH_TIMES.sort((a, b) => a - b);
})();

