'use strict';
/* =====================================================================
   FX: spray, tyre smoke, skid-block sparks, heat shimmer, grandstand flashes.
   Every particle is a closed-form function of simTime: it has a seeded emission
   time and birth state (sampled from the cars' known paths); position at time t
   = birth + v*(1-exp(-k age))/k + g*age^2/2 (evaluated in the vertex shader).
   ===================================================================== */
const FXU = { uTime: { value: 0 }, uRain: { value: new THREE.Vector2(0, 0) } };
const FX = { fields: [], shimmer: [], flashes: null };

const PART_VERT = [
  'attribute vec3 aP; attribute vec4 aV; attribute vec4 aT; attribute vec4 aX;',
  'uniform float uTime; uniform float uDrag; uniform vec3 uGrav; uniform vec2 uRain; uniform float fogDensity;',
  'varying vec2 vUv; varying float vK; varying float vAlpha; varying float vLight; varying float vTint; varying float vFog;',
  'void main(){',
  '  float age = uTime - aT.x;',
  '  vUv = position.xy; vK = 1.0; vAlpha = 0.0; vLight = 0.0; vTint = 0.0; vFog = 0.0;',
  '  if (age < 0.0 || age > aT.y) { gl_Position = vec4(2.0, 2.0, 2.0, 1.0); return; }',
  '  float k = age / aT.y;',
  '  float dd = uDrag > 0.0001 ? (1.0 - exp(-uDrag * age)) / uDrag : age;',
  '  vec3 wp = aP + aV.xyz * dd + 0.5 * uGrav * age * age;',
  '  #ifdef GROUND',
  '  wp.y = max(wp.y, aX.w);',
  '  #endif',
  '  float size = mix(aT.z, aT.w, sqrt(k));',
  '  vec4 mv = viewMatrix * vec4(wp, 1.0);',
  '  mv.xy += position.xy * size;',
  '  gl_Position = projectionMatrix * mv;',
  '  vK = k; vAlpha = aV.w; vLight = aX.y;',
  '  float on = aX.x < 0.5 ? uRain.x : uRain.y;',
  '  vTint = aX.z * on * exp(-age * 1.3);',
  '  float depth = -mv.z; vFog = exp(-fogDensity * fogDensity * depth * depth);',
  '}'].join('\n');
const PUFF_FRAG = [
  'varying vec2 vUv; varying float vK; varying float vAlpha; varying float vLight; varying float vTint; varying float vFog;',
  'void main(){',
  '  float r2 = dot(vUv, vUv); if (r2 > 1.0) discard;',
  '  float soft = exp(-r2 * 3.0) * (1.0 - r2);',
  '  float a = soft * vAlpha * smoothstep(0.0, 0.07, vK) * (1.0 - vK * vK) * vFog;',
  '  vec3 base = mix(vec3(0.045, 0.062, 0.088), vec3(0.58, 0.70, 0.92), clamp(vLight, 0.0, 1.0));',
  '  vec3 c = base + vec3(1.0, 0.10, 0.05) * vTint * 0.6;',
  '  gl_FragColor = vec4(c, a);',
  '}'].join('\n');
const SPARK_FRAG = [
  'varying vec2 vUv; varying float vK; varying float vAlpha; varying float vLight; varying float vTint; varying float vFog;',
  'void main(){',
  '  float r2 = dot(vUv, vUv); if (r2 > 1.0) discard;',
  '  float core = exp(-r2 * 4.5);',
  '  vec3 hot = mix(vec3(1.0, 0.32, 0.05), vec3(1.0, 0.92, 0.72), 1.0 - vK);',
  '  float a = core * vAlpha * (1.0 - vK) * vFog;',
  '  gl_FragColor = vec4(hot * 1.6, a);',
  '}'].join('\n');

class PField {
  constructor(name, max, o) {
    this.name = name; this.max = max; this.n = 0; this.o = o;
    this.P = new Float32Array(max * 3); this.V = new Float32Array(max * 4); this.T = new Float32Array(max * 4); this.X = new Float32Array(max * 4);
  }
  push(te, life, p, v, s0, s1, alpha, light, car, tint, ground) {
    if (this.n >= this.max) return;
    const i = this.n++;
    this.P[i * 3] = p.x; this.P[i * 3 + 1] = p.y; this.P[i * 3 + 2] = p.z;
    this.V[i * 4] = v.x; this.V[i * 4 + 1] = v.y; this.V[i * 4 + 2] = v.z; this.V[i * 4 + 3] = alpha;
    this.T[i * 4] = te; this.T[i * 4 + 1] = life; this.T[i * 4 + 2] = s0; this.T[i * 4 + 3] = s1;
    this.X[i * 4] = car; this.X[i * 4 + 1] = light; this.X[i * 4 + 2] = tint; this.X[i * 4 + 3] = ground;
  }
  build() {
    const n = this.n, g = new THREE.InstancedBufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute([-1, -1, 0, 1, -1, 0, 1, 1, 0, -1, 1, 0], 3));
    g.setIndex([0, 1, 2, 0, 2, 3]);
    g.setAttribute('aP', new THREE.InstancedBufferAttribute(this.P.slice(0, n * 3), 3));
    g.setAttribute('aV', new THREE.InstancedBufferAttribute(this.V.slice(0, n * 4), 4));
    g.setAttribute('aT', new THREE.InstancedBufferAttribute(this.T.slice(0, n * 4), 4));
    g.setAttribute('aX', new THREE.InstancedBufferAttribute(this.X.slice(0, n * 4), 4));
    g.instanceCount = n;
    const o = this.o;
    const m = new THREE.ShaderMaterial({
      uniforms: { uTime: FXU.uTime, uRain: FXU.uRain, uDrag: { value: o.drag }, uGrav: { value: new THREE.Vector3(o.grav[0], o.grav[1], o.grav[2]) }, fogDensity: { value: FOG_DENSITY } },
      vertexShader: (o.ground ? '#define GROUND\n' : '') + PART_VERT,
      fragmentShader: o.spark ? SPARK_FRAG : PUFF_FRAG,
      transparent: true, depthWrite: false, depthTest: true,
      blending: o.spark ? THREE.AdditiveBlending : THREE.NormalBlending
    });
    this.mesh = new THREE.Mesh(g, m); this.mesh.frustumCulled = false; this.mesh.name = 'fx_' + this.name; this.mesh.renderOrder = o.spark ? 7 : 4;
    G.scene.add(this.mesh);
    return this;
  }
}

function buildFX() {
  const r = mulberry32(SIM_SEED + 1000);                 // dedicated seeded stream (seed derived from 42) so FX never perturbs geometry order
  const spray = new PField('spray', 12000, { drag: 1.25, grav: [0, -0.7, 0] });
  const smoke = new PField('smoke', 2600, { drag: 0.9, grav: [0, 0.32, 0] });
  const sparks = new PField('sparks', 14000, { drag: 0.55, grav: [0, -9.8, 0], spark: true, ground: true });
  const po = {}, wp = new THREE.Vector3(), pv = new THREE.Vector3(), vel = new THREE.Vector3();
  const wheelWorld = (i, te, lx, ly, lz, out) => { carPose(i, te, po); carLocalToWorld(po, lx, ly, lz, out); return po; };
  const lightAt = (p) => clamp(bakeAt(p.x, p.y + 0.4, p.z, 0, 1, 0) * 1.25, 0, 1);

  for (let i = 0; i < 2; i++) {
    // ---- water spray from the two rear tyres + a finer mist from the front pair, only while moving fast enough ----
    const rate = 78;
    for (let side = -1; side <= 1; side += 2) {
      for (let k = 0; ; k++) {
        const te = 3.2 + (k + r()) / rate; if (te > DURATION) break;
        const kin = carKin(i, te); if (kin.v < 6) continue;
        if (r() > clamp((kin.v - 5) / 36, 0.15, 1)) continue;
        wheelWorld(i, te, -1.9, -0.02, side * (0.55 + r() * 0.45), wp);
        const v = kin.v, hx = po.hx, hz = po.hz;
        vel.set(hx * v * (0.18 + 0.30 * r()) + (r() - 0.5) * 2.2 * -hz, 1.4 + 2.8 * r(), hz * v * (0.18 + 0.30 * r()) + (r() - 0.5) * 2.2 * hx);
        spray.push(te, 1.1 + 1.0 * r(), wp, vel, 0.30 + 0.3 * r(), 1.5 + 1.9 * r(), clamp(0.05 + v / 480, 0.06, 0.20), lightAt(wp), i, 1.0, 0);
      }
    }
    // ---- launch: tyre smoke + water mist from the spinning rear tyres (t = 3.0 - 6.4) ----
    for (let side = -1; side <= 1; side += 2) {
      for (let k = 0; k < 330; k++) {
        const u = k / 330, te = 3.04 + 2.5 * Math.pow(u, 0.9) + r() * 0.01;
        const kin = carKin(i, te);
        wheelWorld(i, te, -1.8, -0.02, side * (0.6 + r() * 0.3), wp);
        vel.set(po.hx * kin.v * 0.30 + (r() - 0.5) * 1.0, 0.5 + 1.1 * r(), po.hz * kin.v * 0.30 + (r() - 0.5) * 1.0);
        smoke.push(te, 2.2 + 1.6 * r(), wp, vel, 0.45 + 0.35 * r(), 2.6 + 2.4 * r(), 0.34 * (1 - 0.45 * u), lightAt(wp) * 0.9 + 0.15, i, 0.6, 0);
      }
    }
  }
