  for (let k = 0; k < 70; k++) {
    const te = 20.05 + k * 0.014 + r() * 0.01;
    wheelWorld(0, te, AXLE_F, -0.02, -0.80 - r() * 0.1, wp);
    const kin = carKin(0, te);
    vel.set(po.hx * kin.v * 0.5 + (r() - 0.5) * 1.4, 0.6 + 1.2 * r(), po.hz * kin.v * 0.5 + (r() - 0.5) * 1.4);
    smoke.push(te, 1.5 + 1.2 * r(), wp, vel, 0.25 + 0.2 * r(), 1.5 + 1.4 * r(), 0.42, lightAt(wp) + 0.2, 0, 0.2, 0);
  }
