  for (let i = 0; i < 2; i++) {
    const rate = 260;
    for (let k = 0; ; k++) {
      const te = 3.5 + (k + r()) / rate; if (te > DURATION) break;
      const kin = carKin(i, te);
      if (!(kin.v > KMH200 || kin.a < -24)) continue;
      const lx = -1.55 + r() * 1.9, lz = (r() - 0.5) * 0.22;
