      vel.set(po.hx * v * (0.80 + 0.15 * r()) + (r() - 0.5) * 6.0 * -po.hz - po.hx * (1.5 + 5 * r()), 0.6 + 2.6 * r(), po.hz * v * (0.80 + 0.15 * r()) + (r() - 0.5) * 6.0 * po.hx - po.hz * (1.5 + 5 * r()));
