'use strict';
/* =====================================================================
   World B: floodlight masts + light cones + bloom glows, start gantry,
   grandstand + crowd, pit wall / pit lane / garages
   ===================================================================== */
function makeLensTex() {
  const c = mkCanvas(256, 128), g = c.getContext('2d');
  g.fillStyle = '#16181c'; g.fillRect(0, 0, 256, 128);
  for (let i = 0; i < 4; i++) for (let j = 0; j < 2; j++) {
    const gr = g.createRadialGradient(i * 64 + 32, j * 64 + 32, 2, i * 64 + 32, j * 64 + 32, 34);
    gr.addColorStop(0, '#ffffff'); gr.addColorStop(0.7, '#dfe9ff'); gr.addColorStop(1, '#8fa6d6');
    g.fillStyle = gr; g.fillRect(i * 64 + 3, j * 64 + 3, 58, 58);
  }
  return canvasTex(c, { aniso: 4 });
}

/* instanced billboard glows (additive, one draw call) */
class GlowField {
  constructor(max) {
    this.max = max; this.n = 0;
    const g = new THREE.InstancedBufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute([-1, -1, 0, 1, -1, 0, 1, 1, 0, -1, 1, 0], 3));
    g.setIndex([0, 1, 2, 0, 2, 3]);
    this.aC = new THREE.InstancedBufferAttribute(new Float32Array(max * 4), 4);     // xyz + size
    this.aK = new THREE.InstancedBufferAttribute(new Float32Array(max * 4), 4);     // rgb + intensity
    this.aC.setUsage(THREE.DynamicDrawUsage); this.aK.setUsage(THREE.DynamicDrawUsage);
    g.setAttribute('aC', this.aC); g.setAttribute('aK', this.aK);
    g.instanceCount = 0;
    const m = new THREE.ShaderMaterial({
      uniforms: { uBoost: { value: 1.0 } },
      vertexShader: [
        'attribute vec4 aC; attribute vec4 aK; varying vec2 vUv; varying vec4 vK;',
        'void main(){',
        '  vec3 toCam = cameraPosition - aC.xyz; float dist = length(toCam);',
        '  vec3 c = aC.xyz + toCam / max(dist, 0.001) * min(1.2, aC.w * 0.3);',
        '  vec4 mv = viewMatrix * vec4(c, 1.0);',
        '  float size = aC.w * (1.0 + dist * 0.0035);',
        '  mv.xy += position.xy * size;',
        '  vUv = position.xy; vK = aK;',
        '  gl_Position = projectionMatrix * mv;',
        '}'].join('\n'),
      fragmentShader: [
        'varying vec2 vUv; varying vec4 vK;',
        'void main(){',
        '  float r2 = dot(vUv, vUv); if (r2 > 1.0) discard;',
        '  float core = exp(-r2 * 26.0), halo = exp(-r2 * 4.2) * 0.42, a = (core + halo) * vK.a * (1.0 - r2);',
        '  gl_FragColor = vec4(vK.rgb, clamp(a, 0.0, 1.0));',
        '}'].join('\n'),
      transparent: true, depthWrite: false, depthTest: true, blending: THREE.AdditiveBlending
    });
    this.mesh = new THREE.Mesh(g, m); this.mesh.frustumCulled = false; this.mesh.renderOrder = 6; this.mesh.name = 'glows';
  }
  add(x, y, z, size, r, g, b, inten) {
    const i = this.n++; this.set(i, x, y, z, size, r, g, b, inten); this.mesh.geometry.instanceCount = this.n; return i;
  }
  set(i, x, y, z, size, r, g, b, inten) {
    this.aC.setXYZW(i, x, y, z, size); this.aK.setXYZW(i, r, g, b, inten); this.aC.needsUpdate = true; this.aK.needsUpdate = true;
  }
  setInt(i, inten) { this.aK.array[i * 4 + 3] = inten; this.aK.needsUpdate = true; }
}

function buildMasts() {
  const n = LAMPS.length, Y = new THREE.Vector3(0, 1, 0), Z = new THREE.Vector3(0, 0, 1);
  const steel = patchMaterial(stdMat({ color: col('#7a828e'), roughness: 0.5, metalness: 0.8, envMapIntensity: 0.9 }), { k1: 5, k2: 0 });
  const poleG = new THREE.CylinderGeometry(0.2, 0.42, 1, 10); poleG.translate(0, 0.5, 0);
  const poles = new THREE.InstancedMesh(poleG, steel, n); poles.name = 'mastPoles'; poles.frustumCulled = false;
  const headMat = stdMat({ color: col('#2a2f38'), roughness: 0.5, metalness: 0.7 });
  const headG = new THREE.BoxGeometry(3.0, 1.35, 0.5);
  const heads = new THREE.InstancedMesh(headG, headMat, n); heads.name = 'mastHeads'; heads.frustumCulled = false;
  const lensG = new THREE.BoxGeometry(2.8, 1.12, 0.05); lensG.translate(0, 0, 0.27);
  const lensMat = new THREE.MeshBasicMaterial({ map: makeLensTex(), color: new THREE.Color(5.5, 6.1, 7.2), fog: true });
  const lenses = new THREE.InstancedMesh(lensG, lensMat, n); lenses.name = 'mastLamps'; lenses.frustumCulled = false;
  const coneG = new THREE.CylinderGeometry(0.05, 1, 1, 28, 1, true);
  const coneMat = new THREE.ShaderMaterial({
    uniforms: { uCol: { value: new THREE.Color(0.55, 0.72, 1.0) }, uInt: { value: 0.16 }, fogDensity: { value: FOG_DENSITY } },
    vertexShader: [
      'varying vec3 vN; varying vec3 vV; varying float vAlong; varying float vDepth;',
      'void main(){',
      '  vec4 p = vec4(position, 1.0);',
      '  vec3 rad = normalize(vec3(position.x, 0.0, position.z) + vec3(1e-5));',
      '  vec3 nn = rad * 0.966 + vec3(0.0, 0.259, 0.0);',
      '  #ifdef USE_INSTANCING',
      '    mat3 rot = mat3(normalize(instanceMatrix[0].xyz), normalize(instanceMatrix[1].xyz), normalize(instanceMatrix[2].xyz));',
      '    nn = rot * nn; p = instanceMatrix * p;',
      '  #endif',
      '  vec4 mv = modelViewMatrix * p;',
      '  vN = normalize(normalMatrix * nn); vV = -mv.xyz; vAlong = 1.0 - uv.y; vDepth = -mv.z;',
      '  gl_Position = projectionMatrix * mv;',
      '}'].join('\n'),
    fragmentShader: [
      'uniform vec3 uCol; uniform float uInt; uniform float fogDensity;',
      'varying vec3 vN; varying vec3 vV; varying float vAlong; varying float vDepth;',
