'use strict';
/* =====================================================================
   World A: floodlight plan + baked pools, terrain, road, verge, kerbs,
   barriers, catch fencing, painted decals
   ===================================================================== */
const MAST_H = 30, MAST_LAT = 12.5;
const W = { mats: {}, meshes: {} };          // world registry

function planLamps() {
