'use strict';
/* =====================================================================
   Synthesized sound (Web Audio only, no files, no music).
   Audio only READS the simulation state: continuous layers are re-tuned every frame from
   simTime; one-shots fire only when forward playback carries simTime across their event time.
   Randomness for noise buffers / variation: own seeded generator (seed 4242).
   ===================================================================== */
const AU = { ctx: null, ok: false, playing: false, master: null, oneShots: [], gear: [1, 1], shift: [{ k: 0, type: 0 }, { k: 0, type: 0 }], lastGearT: [0, 0] };
const arng = mulberry32(4242);
const SOUND_C = 343;
const GEAR_UP = [13.5, 22, 31, 40, 48.5, 57, 65.5];          // m/s upshift speeds for gears 1..7 (8th above)
const MASTER_LEVEL = 0.62;
const AU_EVENTS = [];                                         // {t, kind}
(function () {
  LIGHT_ON_TIMES.forEach(t => AU_EVENTS.push({ t: t, kind: 'beep' }));
  AU_EVENTS.push({ t: DRS_OPEN_T, kind: 'drsOpen' });
  AU_EVENTS.push({ t: T_FIN_B, kind: 'drsClose' });
  AU_EVENTS.push({ t: T_FIN_B, kind: 'cheer' });
  FLASH_TIMES.forEach(t => AU_EVENTS.push({ t: t, kind: 'shutter' }));
  AU_EVENTS.sort((a, b) => a.t - b.t);
})();

function audioInit() {
  const AC = window.AudioContext || window.webkitAudioContext;
  if (!AC) return;
  const ctx = new AC();
  AU.ctx = ctx;
  const resume = () => { try { const p = ctx.resume(); if (p && p.catch) p.catch(() => {}); } catch (e) { /* ignored */ } };
  resume();
  window.addEventListener('pointerdown', resume, true);
  window.addEventListener('keydown', resume, true);
  buildAudioGraph(ctx);
  AU.ok = true;
}

function makeNoise(ctx, kind, seconds) {
  const n = Math.floor(ctx.sampleRate * seconds), buf = ctx.createBuffer(1, n, ctx.sampleRate), d = buf.getChannelData(0);
  let b0 = 0, b1 = 0, b2 = 0, last = 0;
  for (let i = 0; i < n; i++) {
    const w = arng() * 2 - 1;
    if (kind === 'white') d[i] = w;
    else if (kind === 'pink') { b0 = 0.99765 * b0 + w * 0.0990460; b1 = 0.96300 * b1 + w * 0.2965164; b2 = 0.57000 * b2 + w * 1.0526913; d[i] = (b0 + b1 + b2 + w * 0.1848) * 0.2; }
    else if (kind === 'brown') { last = (last + 0.02 * w) / 1.02; d[i] = last * 3.2; }
    else if (kind === 'crackle') { d[i] = (arng() < 0.012 ? (arng() * 2 - 1) * 2.2 : w * 0.05); }
  }
  // loop-friendly end: crossfade last 256 samples into the start
  for (let i = 0; i < 256; i++) { const k = i / 256; d[n - 256 + i] = d[n - 256 + i] * (1 - k) + d[i] * k; }
