function mkPanner(ctx, ref, roll) {
  const p = ctx.createPanner();
  p.panningModel = 'HRTF'; p.distanceModel = 'inverse'; p.refDistance = ref; p.rolloffFactor = roll; p.maxDistance = 20000;
  return p;
}

const ENGINE_FLAVORS = [
  { mult: [1, 2, 3, 4, 6, 0.5], types: ['sawtooth', 'sawtooth', 'square', 'sawtooth', 'sawtooth', 'sine'], gains: [0.40, 0.30, 0.17, 0.14, 0.08, 0.26], detune: 0, turbo: 1.0 },      // red 7: brighter, more even harmonics
  { mult: [1, 2, 3, 4, 6, 0.5], types: ['sawtooth', 'square', 'sawtooth', 'sawtooth', 'square', 'sine'], gains: [0.34, 0.13, 0.28, 0.12, 0.12, 0.32], detune: 11, turbo: 0.8 }     // blue 23: lower, rounder, odd-harmonic heavy
];

function buildAudioGraph(ctx) {
  const comp = ctx.createDynamicsCompressor();
  comp.threshold.value = -16; comp.knee.value = 14; comp.ratio.value = 6; comp.attack.value = 0.004; comp.release.value = 0.2;
  const master = gn(ctx, 0);
  master.connect(comp); comp.connect(ctx.destination);
  AU.master = master; AU.comp = comp;
  AU.bus = gn(ctx, 1); AU.bus.connect(master);
  AU.nWhite = makeNoise(ctx, 'white', 3); AU.nPink = makeNoise(ctx, 'pink', 4); AU.nBrown = makeNoise(ctx, 'brown', 4); AU.nCrackle = makeNoise(ctx, 'crackle', 2);
  AU.cars = [];
  for (let i = 0; i < 2; i++) {
    const fl = ENGINE_FLAVORS[i];
    const panner = mkPanner(ctx, 12, 0.8), carBus = gn(ctx, 1); carBus.connect(panner); panner.connect(AU.bus);
    // --- engine: V6 turbo-hybrid voice ---
    const eng = gn(ctx, 0), lp = bq(ctx, 'lowpass', 3000, 0.8); lp.connect(eng); eng.connect(carBus);
    const oscs = fl.mult.map((m, k) => { const o = ctx.createOscillator(); o.type = fl.types[k]; o.frequency.value = 200 * m; const g = gn(ctx, fl.gains[k]); o.connect(g); g.connect(lp); o.start(); return { o: o, g: g, m: m }; });
