def main():
    head = open(os.path.join(SRC, "00_head.html"), encoding="utf-8").read()
    parts = sorted(glob.glob(os.path.join(SRC, "[1-9]*.js")))
    js = "\n".join("/* ---- %s ---- */\n%s" % (os.path.basename(p), open(p, encoding="utf-8").read()) for p in parts)
    if "</script" in js.lower():
        print("ERROR: </script found in JS"); sys.exit(1)
    if "Math.random" in js:
        print("WARNING: Math.random referenced in JS")
    # syntax check using jsc: parse only via new Function
    chk = os.path.join(TMP, "build", "_chk.js")
    with open(chk, "w", encoding="utf-8") as f:
        f.write("try { new Function(read(%s)); print('SYNTAX OK'); } catch (e) { print('SYNTAX ERROR: ' + e + ' line ' + (e.line||'?') + ' col ' + (e.column||'?')); }\n" % repr(os.path.join(TMP, "build", "_main.js")))
    with open(os.path.join(TMP, "build", "_main.js"), "w", encoding="utf-8") as f:
        f.write(js)
    r = subprocess.run([JSC, chk], capture_output=True, text=True)
    print((r.stdout + r.stderr).strip())
    if "SYNTAX OK" not in r.stdout:
        sys.exit(2)
    final = head.replace("/*__MAIN_SCRIPT__*/", js)
    with open(OUT_FINAL, "w", encoding="utf-8") as f:
        f.write(final)
    test = final.replace(CDN, ERRHOOK + LOCAL).replace("</body>", TESTHOOK + "</body>")
    with open(OUT_TEST, "w", encoding="utf-8") as f:
        f.write(test)
    print("built: final %d bytes, js %d bytes, %d lines" % (len(final.encode()), len(js.encode()), js.count("\n")))


main()

