    js = "\n".join("/* ---- %s ---- */\n%s" % (os.path.basename(p), open(p, encoding="utf-8").read()) for p in parts)
    if "</script" in js.lower():
        print("ERROR: </script found in JS"); sys.exit(1)
    if "Math.random" in js:
        print("WARNING: Math.random referenced in JS")
    # syntax check using jsc: parse only via new Function
    chk = os.path.join(TMP, "build", "_chk.js")
    with open(chk, "w", encoding="utf-8") as f:
        f.write("try { new Function(read(%s)); print('SYNTAX OK'); } catch (e) { print('SYNTAX ERROR: ' + e + ' line ' + (e.line||'?') + ' col ' + (e.column||'?')); }\n" % repr(os.path.join(TMP, "build", "_main.js")))
